# WorldView Online - Step 18b
# Make one-way ANOVA grouping flexible: country, binary variables, or Q289.

app_dir <- "worldview_static_app"
index_path <- file.path(app_dir, "index.html")
anova_path <- file.path(app_dir, "assets", "anova.js")

if (!all(file.exists(c(index_path, anova_path)))) {
  stop("Run Step 18 first.")
}

html <- paste(readLines(index_path, warn = FALSE), collapse = "\n")

old_controls <- '<label class="field"><span>Outcome variable</span><select id="anova-outcome" required></select></label>\n            <label class="field"><span>Countries</span><select id="anova-countries" multiple size="12" required></select></label>\n            <p class="field-help">Select between two and ten countries. Country is the categorical predictor.</p>'

new_controls <- '<label class="field"><span>Outcome variable</span><select id="anova-outcome" required></select></label>\n            <label class="field"><span>Grouping variable</span><select id="anova-group" required></select></label>\n            <label class="field"><span>Countries included</span><select id="anova-countries" multiple size="10"></select></label>\n            <p id="anova-country-help" class="field-help">When Country is the grouping variable, select between two and ten countries. For other grouping variables, these countries filter the sample; if none are selected, all countries are included.</p>'

if (grepl(old_controls, html, fixed = TRUE)) {
  html <- sub(old_controls, new_controls, html, fixed = TRUE)
} else if (!grepl('id="anova-group"', html, fixed = TRUE)) {
  stop("Could not find the Step 18 ANOVA controls.")
}

html <- sub(
  "Compare the mean of one numeric or scale-like outcome across two or more selected countries.",
  "Compare the mean of one numeric or scale-like outcome across categories of country, sex, denomination, or another binary variable.",
  html,
  fixed = TRUE
)
writeLines(html, index_path, useBytes = TRUE)

anova_js <- '"use strict";
const anovaPaths={data:"data/worldview-browser-data-v1.0.0.json",codebook:"data/worldview-codebook-v1.0.0.json"};
const anovaState={data:null,outcomes:[],groups:[],countries:[],lastRows:[]};
const aEsc=v=>String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;");
const aFmt=(v,d=3)=>v==null||!Number.isFinite(v)?"Not available":new Intl.NumberFormat("en-NZ",{minimumFractionDigits:d,maximumFractionDigits:d}).format(v);
const aSelected=id=>[...document.getElementById(id).selectedOptions].map(o=>o.value);
function aParse(o){const n=Object.keys(o),l=o[n[0]].length;if(!n.length||!n.every(k=>o[k].length===l))throw Error("Invalid data");return{columns:o,length:l};}
function aLabel(variable,value){if(variable.id==="COUNTRY")return String(value);if(variable.id==="Q289")return String(value);if(["Q165","Q166","Q167","Q168"].includes(variable.id))return Number(value)===1?"Yes":"No";if(variable.id==="Q260")return Number(value)===1?"Male":"Female";if(variable.id==="Q263")return Number(value)===1?"Born in this country":"Immigrant to this country";return String(value);}
function aNormalCdf(x){const s=x<0?-1:1,z=Math.abs(x)/Math.sqrt(2),t=1/(1+.3275911*z),e=1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-z*z);return .5*(1+s*e);}
function aFCdfApprox(f,df1,df2){if(!Number.isFinite(f)||f<0)return null;const z=(Math.log(f)-Math.log(df2/(df2-2)))/Math.sqrt(2/df1+2/(df2-4));return aNormalCdf(z);}
function buildGroups(outcomeId,groupId,countryCodes){const allowed=new Set(countryCodes),cc=anovaState.data.columns.B_COUNTRY_ALPHA,cn=anovaState.data.columns.B_COUNTRY,out=anovaState.data.columns[outcomeId],groupVar=anovaState.groups.find(v=>v.id===groupId),map=new Map();for(let i=0;i<anovaState.data.length;i++){if(allowed.size&&!allowed.has(cc[i]))continue;const y=out[i];if(y===null||y===""||!Number.isFinite(Number(y)))continue;let raw,label;if(groupId==="COUNTRY"){raw=cc[i];label=cn[i];}else{raw=anovaState.data.columns[groupId][i];if(raw===null||raw==="")continue;label=aLabel(groupVar,raw);}const key=String(raw);if(!map.has(key))map.set(key,{key,label,values:[]});map.get(key).values.push(Number(y));}return[...map.values()].map(g=>{const n=g.values.length,mean=g.values.reduce((s,v)=>s+v,0)/n,variance=n>1?g.values.reduce((s,v)=>s+(v-mean)**2,0)/(n-1):null;return{...g,n,mean,sd:variance==null?null:Math.sqrt(variance)};}).filter(g=>g.n>=2).sort((a,b)=>a.label.localeCompare(b.label));}
function calculateAnova(e){e.preventDefault();const outcome=document.getElementById("anova-outcome").value,groupId=document.getElementById("anova-group").value,countries=aSelected("anova-countries");if(groupId==="COUNTRY"&&(countries.length<2||countries.length>10)){document.getElementById("anova-message").textContent="When grouping by country, select between two and ten countries.";return;}const groups=buildGroups(outcome,groupId,countries);if(groups.length<2){document.getElementById("anova-message").textContent="At least two grouping categories with two or more valid observations are required.";return;}const totalN=groups.reduce((s,g)=>s+g.n,0),grand=groups.reduce((s,g)=>s+g.n*g.mean,0)/totalN,ssB=groups.reduce((s,g)=>s+g.n*(g.mean-grand)**2,0),ssW=groups.reduce((s,g)=>s+g.values.reduce((q,v)=>q+(v-g.mean)**2,0),0),dfB=groups.length-1,dfW=totalN-groups.length,msB=ssB/dfB,msW=ssW/dfW,f=msB/msW,eta=ssB/(ssB+ssW),omega=(ssB-dfB*msW)/(ssB+ssW+msW),p=1-aFCdfApprox(f,dfB,dfW),outVar=anovaState.outcomes.find(v=>v.id===outcome),groupName=groupId==="COUNTRY"?"Country":anovaState.groups.find(v=>v.id===groupId).displayName;document.getElementById("anova-title").textContent=`${outcome} by ${groupName}`;document.getElementById("anova-message").textContent=`${groupName} is treated as the categorical predictor. ${outVar.analysisType==="ordinal"?"The ordered outcome is treated as an equally spaced numerical scale.":""}`;document.getElementById("anova-results").innerHTML=`<section class="regression-card"><div class="model-fit-grid"><div><strong>${aFmt(totalN,0)}</strong><span>Valid observations</span></div><div><strong>${aFmt(groups.length,0)}</strong><span>Groups</span></div><div><strong>${aFmt(f)}</strong><span>F(${dfB}, ${dfW})</span></div><div><strong>${p<.001?"&lt; 0.001":aFmt(p)}</strong><span>Approximate p-value</span></div><div><strong>${aFmt(eta)}</strong><span>Eta squared</span></div><div><strong>${aFmt(omega)}</strong><span>Omega squared</span></div></div><div class="table-wrap"><table class="results-table"><thead><tr><th>${aEsc(groupName)}</th><th>Valid n</th><th>Mean</th><th>SD</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${aEsc(g.label)}</td><td>${aFmt(g.n,0)}</td><td>${aFmt(g.mean)}</td><td>${aFmt(g.sd)}</td></tr>`).join("")}</tbody></table></div><h4>ANOVA table</h4><div class="table-wrap"><table class="results-table"><thead><tr><th>Source</th><th>SS</th><th>df</th><th>MS</th><th>F</th></tr></thead><tbody><tr><td>Between groups</td><td>${aFmt(ssB)}</td><td>${dfB}</td><td>${aFmt(msB)}</td><td>${aFmt(f)}</td></tr><tr><td>Within groups</td><td>${aFmt(ssW)}</td><td>${dfW}</td><td>${aFmt(msW)}</td><td></td></tr></tbody></table></div><p class="model-note">This omnibus test indicates whether at least one group mean differs. It does not identify which pairs differ. The p-value is a browser approximation.</p></section>`;document.getElementById("anova-download").hidden=false;anovaState.lastRows=groups.map(g=>({outcome,grouping_variable:groupId,group:g.label,valid_n:g.n,mean:g.mean,standard_deviation:g.sd,f_statistic:f,df_between:dfB,df_within:dfW,approximate_p_value:p,eta_squared:eta,omega_squared:omega}));}
function downloadAnova(){if(!anovaState.lastRows.length)return;const cols=Object.keys(anovaState.lastRows[0]),q=v=>`"${String(v??"").replaceAll("\\\"","\\\"\\\"")}"`,text=[cols.join(","),...anovaState.lastRows.map(r=>cols.map(c=>q(r[c])).join(","))].join("\\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type:"text/csv"}));a.download="worldview-one-way-anova.csv";a.click();URL.revokeObjectURL(a.href);}
function updateAnovaHelp(){const country=document.getElementById("anova-group").value==="COUNTRY";document.getElementById("anova-country-help").textContent=country?"Select between two and ten countries. Each selected country is a group.":"Selected countries filter the sample. If none are selected, all countries are included; categories of the grouping variable form the groups.";}
function resetAnova(){document.getElementById("anova-form").reset();document.getElementById("anova-outcome").value="Q177";document.getElementById("anova-group").value="COUNTRY";[...document.getElementById("anova-countries").options].forEach(o=>o.selected=["AUS","NZL"].includes(o.value));document.getElementById("anova-results").innerHTML="";document.getElementById("anova-download").hidden=true;updateAnovaHelp();}
function limitCountries(){const x=[...document.getElementById("anova-countries").selectedOptions];if(document.getElementById("anova-group").value==="COUNTRY"&&x.length>10){x.slice(10).forEach(o=>o.selected=false);document.getElementById("anova-message").textContent="Select no more than ten country groups.";}}
async function initialiseAnova(){const loading=document.getElementById("anova-loading");try{const[d,c]=await Promise.all([fetch(anovaPaths.data).then(r=>r.json()),fetch(anovaPaths.codebook).then(r=>r.json())]);anovaState.data=aParse(d);anovaState.outcomes=c.variables.filter(v=>v.analysisType==="integer"||v.analysisType==="ordinal");anovaState.groups=[{id:"COUNTRY",displayName:"Country",analysisType:"nominal"},...c.variables.filter(v=>v.analysisType==="binary"||v.analysisType==="nominal")];const pairs=new Map();for(let i=0;i<anovaState.data.length;i++)pairs.set(anovaState.data.columns.B_COUNTRY_ALPHA[i],anovaState.data.columns.B_COUNTRY[i]);anovaState.countries=[...pairs].map(([code,name])=>({code,name})).sort((a,b)=>a.name.localeCompare(b.name));const out=document.getElementById("anova-outcome"),grp=document.getElementById("anova-group");anovaState.outcomes.forEach(v=>out.add(new Option(`${v.id}: ${v.displayName}`,v.id)));anovaState.groups.forEach(v=>grp.add(new Option(v.id==="COUNTRY"?"Country":`${v.id}: ${v.displayName}`,v.id)));out.value="Q177";grp.value="COUNTRY";const cs=document.getElementById("anova-countries");anovaState.countries.forEach(c=>{const o=new Option(`${c.name} (${c.code})`,c.code);if(["AUS","NZL"].includes(c.code))o.selected=true;cs.add(o);});loading.hidden=true;document.getElementById("anova-form").hidden=false;updateAnovaHelp();}catch(error){loading.textContent=`ANOVA data could not be loaded: ${error.message}`;}}
document.addEventListener("DOMContentLoaded",()=>{document.getElementById("anova-form").addEventListener("submit",calculateAnova);document.getElementById("anova-reset").addEventListener("click",resetAnova);document.getElementById("anova-download").addEventListener("click",downloadAnova);document.getElementById("anova-countries").addEventListener("change",limitCountries);document.getElementById("anova-group").addEventListener("change",updateAnovaHelp);initialiseAnova();});'

writeLines(anova_js, anova_path, useBytes = TRUE)

checks <- data.frame(
  check=c("group_selector_added","country_group_available","binary_groups_available","nominal_group_available","country_filter_logic_added","at_least_two_groups_required","download_includes_grouping_variable"),
  passed=c(grepl('id="anova-group"',html,fixed=TRUE),grepl('id:"COUNTRY"',anova_js,fixed=TRUE),grepl('v.analysisType==="binary"',anova_js,fixed=TRUE),grepl('v.analysisType==="nominal"',anova_js,fixed=TRUE),grepl("allowed.size",anova_js,fixed=TRUE),grepl("groups.length<2",anova_js,fixed=TRUE),grepl("grouping_variable:groupId",anova_js,fixed=TRUE))
write.csv(checks,file.path(app_dir,"step18b_validation_checks.csv"),row.names=FALSE)
if(!all(checks$passed))stop("Step 18b validation failed: ",paste(checks$check[!checks$passed],collapse=", "))
cat("\nStep 18b completed successfully.\nRestart with:\n  servr::httd(\"worldview_static_app\", browser = TRUE)\n")
